```rust
fn find_matching_constraint<'a>(
    constraints: &'a [Constraint],
    from_path: &str,
    to_path: &str,
    file_to_component: &HashMap<String, String>,
) -> Option<&'a Constraint> {
    let opts = MatchOptions { require_literal_separator: true, ..Default::default() };
    constraints.iter().find(|c| match &c.kind {
        ConstraintKind::ForbiddenDep { from, to } => {
            Pattern::new(from).ok().map_or(false, |fp| fp.matches_with(from_path, opts))
                && Pattern::new(to).ok().map_or(false, |tp| tp.matches_with(to_path, opts))
        }
        ConstraintKind::Boundary { from_component, to_component } => {
            file_to_component.get(from_path).map_or(false, |c| c == from_component || /* name match */)
                && file_to_component.get(to_path).map_or(false, |c| c == to_component || /* name match */)
        }
        _ => false,
    })
}

fn build_component_context(
    kind: &ConstraintKind,
    file_to_component: &HashMap<String, String>,
    from_path: &str,
    to_path: &str,
) -> Option<String> {
    match kind {
        ConstraintKind::Boundary { from_component, to_component } =>
            Some(format!("{from_component} -> {to_component}")),
        _ => {
            let from_c = file_to_component.get(from_path);
            let to_c = file_to_component.get(to_path);
            match (from_c, to_c) {
                (Some(f), Some(t)) if f != t => Some(format!("{f} -> {t}")),
                _ => None,
            }
        }
    }
}

fn format_violation_detail(
    c: &Constraint, from: &str, to: &str, is_introduced: bool,
) -> String {
    let delta = if is_introduced { " [introduced]" } else { "" };
    match &c.kind {
        ConstraintKind::ForbiddenDep { from: rf, to: rt } =>
            format!("forbidden: {from} -> {to} (rule: {rf} -> {rt}){delta}"),
        ConstraintKind::Boundary { from_component, to_component } =>
            format!("boundary: {from} -> {to} ({from_component} -> {to_component}){delta}"),
        _ => format!("{}: {from} -> {to}{delta}", c.kind.kind_tag()),
    }
}
```

